const defaultTemplate=currentSpreadCatalog.templates.find(template=>template.categoryId==='category-everyday'&&template.slug==='persona-obstacle-solution')!;
const defaultPositions=currentSpreadCatalog.positions.filter(position=>position.templateId===defaultTemplate.id).sort((left,right)=>left.order-right.order);
const initial:State={phase:'ready',deck:'Rider Waite Smith',spread:defaultPositions.map(position=>position.label.en),categoryId:'category-everyday',spreadTemplateId:defaultTemplate.id,optionalContext:'',sessionId:null,drawPlan:[],theme:'light',reversals:true,question:'',topic:null,cards:[],notes:'',drawing:'',texts:[]};

function localCatalogFor(locale:TarotLocale):TarotCatalog{
 return {locale,categories:currentSpreadCatalog.categories.map(category=>({
  ...category,
  name:category.name[locale],
  description:category.description[locale],
  templates:currentSpreadCatalog.templates.filter(template=>template.categoryId===category.id).sort((left,right)=>left.displayOrder-right.displayOrder).map(template=>({
   ...template,
   name:template.name[locale],
   description:template.description[locale],
   positions:currentSpreadCatalog.positions.filter(position=>position.templateId===template.id).sort((left,right)=>left.order-right.order).map(position=>({...position,label:position.label[locale],description:position.description[locale],prompt:position.prompt[locale]})),
  })),
 }))};
}

function normalizeCatalog(value:unknown,locale:TarotLocale):TarotCatalog{
 const candidate=value&&typeof value==='object'?value as Partial<TarotCatalog>:{};
 return candidate.locale===locale&&Array.isArray(candidate.categories)?value as TarotCatalog:localCatalogFor(locale);
}

function normalizeRoomState(value:unknown):State{
 const raw=value&&typeof value==='object'?value as Partial<State>:{};
 const rawSpread=Array.isArray(raw.spread)&&raw.spread.length?raw.spread.filter((label):label is string=>typeof label==='string').slice(0,10):initial.spread;
 const legacy=hydrateLegacySpread(rawSpread);
 const cards=Array.isArray(raw.cards)?raw.cards.filter((card:any)=>Boolean(card&&typeof card==='object'&&typeof card.id==='number')).slice(0,78).map((card:any)=>({
  id:card.id,
  cardNumber:typeof card.cardNumber==='number'?card.cardNumber:card.id,
  cardId:typeof card.cardId==='string'?card.cardId:undefined,
  readingCardId:typeof card.readingCardId==='string'?card.readingCardId:undefined,
  positionKey:typeof card.positionKey==='string'?card.positionKey:undefined,
  positionOrder:typeof card.positionOrder==='number'?card.positionOrder:undefined,
  reversed:Boolean(card.reversed),
  orientation:card.orientation==='reversed'||card.orientation==='upright'?card.orientation:(card.reversed?'reversed':'upright'),
  face:Boolean(card.face),
  x:typeof card.x==='number'?card.x:0,
  y:typeof card.y==='number'?card.y:0,
 })):[];
 return {
  ...initial,
  ...raw,
  phase:raw.phase==='ready'||raw.phase==='shuffling'||raw.phase==='drawing'?raw.phase:initial.phase,
  spread:rawSpread,
  categoryId:typeof raw.categoryId==='string'?raw.categoryId:(legacy?.categoryId||initial.categoryId),
  spreadTemplateId:typeof raw.spreadTemplateId==='string'?raw.spreadTemplateId:(legacy?.templateId||initial.spreadTemplateId),
  optionalContext:typeof raw.optionalContext==='string'?raw.optionalContext.slice(0,5000):'',
  sessionId:typeof raw.sessionId==='string'?raw.sessionId:null,
  drawPlan:Array.isArray(raw.drawPlan)?raw.drawPlan.filter((card):card is RoomPlanCard=>Boolean(card&&typeof card==='object'&&typeof (card as any).cardNumber==='number')).slice(0,10):[],
  question:typeof raw.question==='string'?raw.question.slice(0,500):'',
  topic:typeof raw.topic==='string'?raw.topic:null,
  cards,
  notes:typeof raw.notes==='string'?raw.notes:'',
  drawing:typeof raw.drawing==='string'?raw.drawing:'',
  texts:Array.isArray(raw.texts)?raw.texts.filter((note):note is RoomText=>Boolean(note&&typeof note==='object'&&typeof (note as any).id==='string')).slice(0,100):[],
 };
}
