    {tab==='overview'&&<div className="interpretation-tab-panel"><div className="room-interpretation-callout"><span>❧</span><p>{interpretation.reading.overview}</p></div><section className="interpretation-section"><h3>{t('room.interpretationPositionDetails')}</h3><div className="reading-detail-grid">{readings.map((reading,index)=>renderCard(reading,index,true))}</div></section><section className="interpretation-section"><h3>{t('room.interpretationConnectionsHeading')}</h3><p>{interpretation.reading.connections}</p></section><section className="interpretation-message-card"><h3>{t('room.interpretationGuidanceHeading')}</h3><p>{interpretation.reading.guidance}</p></section><section className="interpretation-section"><h3>{t('room.interpretationClosingHeading')}</h3><p>{interpretation.reading.closing}</p></section><p className="room-interpretation-disclaimer">{interpretation.reading.disclaimer}</p></div>}
    {tab==='cards'&&<div className="interpretation-tab-panel"><div className="interpretation-section"><h3>{t('room.interpretationCardsTab')}</h3><div className="reading-detail-list">{readings.map((reading,index)=>renderCard(reading,index))}</div></div></div>}
